_CANONICAL = [
    (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
    (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
    (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I'),
]


def _to_canonical(n):
    out = []
    for value, symbol in _CANONICAL:
        count, n = divmod(n, value)
        out.append(symbol * count)
    return ''.join(out)


def from_roman(s):
    """Value of a Roman numeral in standard form (1..3999). Anything not in standard form
    (for example IIII, VX, IC, MMMM, lower case, empty) raises ValueError."""
    if not isinstance(s, str) or not s or any(ch not in _VALUES for ch in s):
        raise ValueError(f'not a Roman numeral in standard form: {s!r}')
    total = 0
    for i, ch in enumerate(s):
        v = _VALUES[ch]
        if i + 1 < len(s) and _VALUES[s[i + 1]] > v:
            total -= v
        else:
            total += v
    # Standard form is unique: the numeral must round-trip exactly and be in range.
    if not 1 <= total <= 3999 or _to_canonical(total) != s:
        raise ValueError(f'not a Roman numeral in standard form: {s!r}')
    return total
